const $=(s)=>document.querySelector(s);const id=new URLSearchParams(location.search).get('id');
const fmt=(v)=>{if(!v)return'时间未知';const d=new Date(v.replace(' ','T')+(v.includes('T')?'':'+08:00'));return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)};
function chart(svg,values,color,unit){const a=values.filter(x=>Number.isFinite(x.value));if(a.length<2){svg.innerHTML='<text x="20" y="40">来源数据不足，无法绘制趋势</text>';return}const min=Math.min(...a.map(x=>x.value)),max=Math.max(...a.map(x=>x.value)),span=max-min||1,points=a.map((x,i)=>`${35+i*630/(a.length-1)},${185-(x.value-min)/span*145}`).join(' ');svg.innerHTML=`<line x1="35" y1="185" x2="665" y2="185" stroke="#bed0cc"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="4"/><text x="35" y="210" font-size="12">${fmt(a[0].time)}</text><text x="540" y="210" font-size="12">${fmt(a.at(-1).time)}</text><text x="38" y="28" font-size="13">${max} ${unit}</text><text x="38" y="180" font-size="13">${min} ${unit}</text>`}
function life(track){const events=[];let last;track.forEach(p=>{if(p.strength&&p.strength!==last){events.push({time:p.time,text:`强度变为${p.strength}（${p.windLevel??'—'}级）`});last=p.strength}});const f=document.createDocumentFragment();events.forEach(e=>{const li=document.createElement('li');li.innerHTML=`<time>${fmt(e.time)}</time><strong>${e.text}</strong>`;f.append(li)});$('#lifecycle').replaceChildren(f)}
fetch('data/typhoon.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()}).then(data=>{const s=data.storms?.find(x=>!id||x.id===id);if(!s)throw new Error('未找到该台风');const p=s.latest;document.title=`${s.name}详情｜海风哨`;$('#detailHealth').textContent=`来源实况 ${fmt(p?.time)} · 页面数据抓取 ${fmt(data.fetchedAt)}`;$('#detailCode').textContent=`TY ${s.id}`;$('#detailName').textContent=s.name;$('#detailEnglish').textContent=s.englishName||'';$('#detailStatus').textContent=s.active?'活动中':'已停止编号';$('#detailSummary').textContent=`${s.name}共有 ${s.track?.length||0} 个实况节点和 ${s.forecast?.length||0} 个${s.forecastAgency||'来源机构'}预测节点。`;$('#dStrength').textContent=p?.strength||'来源未提供';$('#dWind').textContent=p?.windLevel?`${p.windLevel}级 · ${p.windSpeed}m/s`:'来源未提供';$('#dPressure').textContent=p?.pressure?`${p.pressure} hPa`:'来源未提供';$('#dMove').textContent=`${p?.moveDirection||'方向未知'} · ${p?.moveSpeed??'—'}km/h`;$('#compareLink').href=`compare.html?current=${encodeURIComponent(s.id)}`;life(s.track||[]);chart($('#windChart'),(s.track||[]).map(x=>({time:x.time,value:x.windSpeed})),'#087f78','m/s');chart($('#pressureChart'),(s.track||[]).map(x=>({time:x.time,value:x.pressure})),'#d98918','hPa');const rows=document.createDocumentFragment();(s.track||[]).forEach(x=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${fmt(x.time)}</td><td>${x.strength||'—'}</td><td>${x.windLevel??'—'}级</td><td>${x.windSpeed??'—'}m/s</td><td>${x.pressure??'—'}hPa</td><td>${x.longitude}°E, ${x.latitude}°N</td>`;rows.append(tr)});$('#detailTable').replaceChildren(rows)}).catch(e=>{$('#detailHealth').textContent='详情数据加载失败';$('#detailName').textContent='无法显示台风详情';$('#detailSummary').textContent=`${e.message}。请返回首页或查看官方来源。`});
